export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";
const FREE_TYPES = 3;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  const distinctNonSphinxMonsters = new Set(
    army.filter((card) => card.monster !== SPHINX).map((card) => card.monster),
  );
  if (distinctNonSphinxMonsters.size > FREE_TYPES) return 3;
  return 2;
};

